INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-hrm301', 'stk-hisham.s', 'HRM 301', 'doc', '{"docs": [{"id": "stk-dr-f98473", "n": "Dr. Razali Bin Mat Zin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 142\nمادة HRM301\n\nترم 152\nمادة HRM401\n\nإدارة الموارد البشرية\n\nعدد الطلاب بالكلاس كان 7\nالتحضير :\nالتحضير يومي يمرر ورقة وتوقع .\nالخصم على الغياب من اول غياب .\nالكويزات :\nإما يعطي 2 وياخذ أفضل واحد\nأو 3 وياخذ أفضل 2\n+\nبونص أساينمنتس\nالمياجر :\nكان اختيارات TB يعدل عليها + كم سؤال عدد وسؤال عن موضوع تشابتر كامل عباره عن case study\n.\nالفاينل نفس المياجر تقريبا .\n\nالقريد النهائي A+\n\nالدكتور متمكن وبقوة من تخصصه ولديه خبره كافيه ومثرية عن الموارد البشرية ونقل التجربة الماليزية\nمتعاون ومتفهم ومتقبل لنقاشات واسئلة الطلاب ومستمع جيد لهم .\n\nالدكتور يشد في المياجر والفاينل ولك أن تتخيل جميع انواع الأسئلة ممكن تجي في إختبار واحد .\n\nلكن بالأخير المادة تكون آفرج.\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433838-hrm301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-razali-bin-mat-zin/98473/14", "user": "hisham.s", "ts": 1447935081000, "tid": 98473, "pn": 14}}]}', 1447935081000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
